{"name": "exec", "call_id": "call_d1181389d7e0476ca73f7a8761a1adc6", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/output/technical-completion-20261019/hardware/accept_candidate.py\n+from pathlib import Path\n+from datetime import datetime, timezone\n+import hashlib, json, re, subprocess, sys, time\n+from serial.tools import list_ports\n+\n+out=Path(__file__).resolve().parent\n+run=out.parent\n+sys.path.insert(0,str(out.parents[1]/'weather-flash-20261018'))\n+from board_console import Console\n+sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()\n+fw=run/'firmware/nuttx.bin'\n+expected='ae92d3c2115d5b6bc0078f2489e3357b5b8dc056505ea7379076307e76a29b6e'\n+backup=json.loads((out/'backup.json').read_text())\n+assert sha(fw)==expected and backup['flash_verified']\n+assert sha(out/'board-before.full.bin')==backup['sha256']\n+assert sha(out/'rollback-application.bin')==backup['rollback_application_sha256']\n+assert ((fw.stat().st_size+0x2000+4095)&~4095)<=0xc00000\n+assert int(json.loads((run/'build-status-final.json').read_text())['ebss'],16)<=0x4ffaefc0\n+ports=[p for p in list_ports.comports() if p.device=='COM4']\n+assert len(ports)==1 and (ports[0].vid,ports[0].pid)==(0x303a,0x1001)\n+assert ports[0].serial_number.lower()=='[REDACTED:mac]'\n+assert not (out/'deployment.json').exists(),'Do not overwrite a deployment attempt'\n+base=[sys.executable,'-m','esptool','--chip','esp32p4','--port','COM4','--baud','460800']\n+report=dict(started_at_utc=datetime.now(timezone.utc).isoformat(),candidate_sha256=expected,\n+    board_written=False,boot_verified=False,restored=False,tests=[],memory_samples=[],\n+    program_offset='0x2000',data_region_written_by_flasher=False,c6_firmware_written=False,\n+    model_files_written=False,sdcard_files_written_by_test=False,\n+    scope='Current candidate only; console-observed basic acceptance, no physical power cycling or human UI/audio assessment.')\n+def save(): (out/'deployment.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')\n+def tool(args,label,timeout=300):\n+    with (out/(label+'.log')).open('w',encoding='utf-8') as log:\n+        subprocess.run(base+args,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=timeout)\n+def flash(path,label,before='usb-reset',after='watchdog-reset'):\n+    tool(['--before',before,'--after',after,'write-flash','0x2000',str(path)],label)\n+    assert 'Hash of data verified' in (out/(label+'.log')).read_text()\n+def connect(log):\n+    end=time.monotonic()+40\n+    while True:\n+        try:return Console('COM4',log)\n+        except Exception:\n+            if time.monotonic()>end:raise\n+            time.sleep(.3)\n+def test(name,passed,**extra):\n+    report['tests'].append(dict(name=name,passed=bool(passed),**extra));save()\n+    assert passed,name\n+    print('CANDIDATE_CHECK_OK',name,flush=True)\n+def boot(c,label):\n+    # Retain every received boot byte privately; Console checks fatal patterns.\n+    end=time.monotonic()+4\n+    while time.monotonic()<end:\n+        c.record(c.serial.read(c.serial.in_waiting or 1).decode(errors='replace'))\n+    uname=c.command('uname -a')\n+    mounts=c.command('mount')\n+    c.command('desktop ui home')\n+    nav=c.command('desktop ui navigation-status')\n+    test(label,'esp32p4-function-ev-board' in uname and '/data type smartfs' in mounts\n+         and '/sdcard type vfat' in mounts and 'navigation page=home' in nav)\n+def memory(c,label):\n+    text=c.command('free'); rows={}\n+    for row in re.finditer(r'^\\s*(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(Umem|Kmem)',text,re.M):\n+        rows[row[8]]={k:int(row[i+1]) for i,k in enumerate(['total','used','free','maxused','maxfree','nused','nfree'])}\n+    assert len(rows)==2\n+    report['memory_samples'].append(dict(label=label,**rows));save()\n+    return rows\n+save()\n+try:\n+    report['write_attempted']=True;save()\n+    flash(fw,'candidate-flash',after='no-reset')\n+    report['board_written']=True;save()\n+    print('CANDIDATE_FLASH_HASH_VERIFIED',flush=True)\n+    # Read the data partition before running the candidate, then reset to boot.\n+    tool(['--before','no-reset','--after','watchdog-reset','read-flash','0xc00000','0x400000',str(out/'data-after-flash.bin')],'data-readback')\n+    preserved=sha(out/'data-after-flash.bin')==backup['data_before_sha256']\n+    report['data_partition_readback_matches_backup']=preserved;save()\n+    test('data_partition_preserved',preserved)\n+    with (out/'board.log').open('w',encoding='utf-8') as log:\n+        c=connect(log)\n+        try:\n+            boot(c,'initial_boot_and_storage')\n+            report['boot_verified']=True;save()\n+            for page,expected_page in [('settings','panel'),('wifi','panel'),('bluetooth','panel'),\n+                                       ('files','panel'),('resources','panel'),('music','panel'),('chat','chat')]:\n+                c.command('desktop ui '+page)\n+                test('navigation_'+page,'navigation page='+expected_page in c.command('desktop ui navigation-status'))\n+                c.command('desktop ui home')\n+                test('return_home_'+page,'navigation page=home' in c.command('desktop ui navigation-status'))\n+            test('chat_status','chat loaded=' in c.command('desktop ui chat-status'))\n+            test('music_status','music state=' in c.command('desktop ui music-status'))\n+            baseline=memory(c,'warm_home')\n+            for i in range(10):\n+                c.command('desktop ui settings');c.command('desktop ui home')\n+                assert 'navigation page=home' in c.command('desktop ui navigation-status')\n+            final=memory(c,'after_ten_navigation_cycles')\n+            delta=final['Umem']['used']-baseline['Umem']['used']\n+            test('ten_settings_home_cycles',delta<32768,heap_used_delta_bytes=delta,\n+                 limit_bytes=32768,note='Bounded observation with concurrent services; not a long-term leak proof.')\n+        finally:c.close()\n+    # The first deployment reset plus four additional watchdog resets = 5 reset boots.\n+    # These are explicitly not power-off cold starts.\n+    for cycle in range(2,6):\n+        tool(['--before','usb-reset','--after','watchdog-reset','chip-id'],'reset-'+str(cycle),60)\n+        with (out/('boot-'+str(cycle)+'.log')).open('w',encoding='utf-8') as log:\n+            c=connect(log)\n+            try:boot(c,'reset_boot_'+str(cycle))\n+            finally:c.close()\n+    report['reset_boots_passed']=5;report['power_off_cold_boots_performed']=0\n+    report['basic_acceptance_passed']=True\n+except Exception as error:\n+    report['error']=repr(error);save()\n+    # A failed boot or a partial write must leave a bootable previous program.\n+    if report.get('write_attempted') and not report['boot_verified']:\n+        print('RESTORING_VERIFIED_PREVIOUS_PROGRAM',flush=True)\n+        flash(out/'rollback-application.bin','restore')\n+        report['restored']=True;save()\n+    raise\n+finally:\n+    report['completed_at_utc']=datetime.now(timezone.utc).isoformat();save()\n+print('NEW_CANDIDATE_BASIC_ACCEPTANCE_DONE',flush=True)\n*** End Patch"));
